const float MinDistance = 0.00001;
const float MaxDistance = 10000.0;
const int MaxStep = 1000;

//Gradient sampler from https://iquilezles.org/articles/palettes/
vec3 palette(float t) 
{
    const vec3 a = vec3(0.5, 0.5, 0.5);
    const vec3 b = vec3(0.5, 0.5, 0.5);
    const vec3 c = vec3(1.0, 1.0, 1.0);
    const vec3 d = vec3(0.00, 0.10, 0.20);
    return a + b * cos(6.28318 * (c * t + d));
}

//Function to create a 2D rotation matrix
mat2 rotate2D(float angle)
{
    float s = sin(angle);
    float c = cos(angle);
    return mat2(c, -s, s, c);
}

float sdfSphere(vec3 position, float radius)
{
    return length(position) - radius;
}

float sdfBox(vec3 position, vec3 size)
{
    vec3 q = abs(position) - size / 2.0;
    float positive = length(max(q, vec3(0.0)));
    float negative = min(max(q.x,max(q.y,q.z)), 0.0);
    return positive + negative;
}

float sdfScene(vec3 position)
{
    position.y += sin(position.z * 0.3);
    position.xy *= rotate2D(0.4 * position.z);

    position = mod(position, vec3(1.0, 1.0, 0.5));
    position -= vec3(0.5, 0.5, 0.35);
    float box = sdfBox(position, vec3(0.2));
    // float sphere = sdfSphere(position - vec3(1.0, 0.0, 0.0), 0.5);



    return box;
}

float rayMarch(vec3 origin, vec3 direction)
{
    float totalDistance = 0.0;

    for (int i = 0; i < MaxStep; i++)
    {
        //March ray forward
        vec3 point = origin + direction * totalDistance;
        float distanceToScene = sdfScene(point);
        totalDistance += distanceToScene;

        //Exit if ray intersected or escaped scene
        if (abs(distanceToScene) < MinDistance) break;
        if (totalDistance > MaxDistance) break;
    }

    return totalDistance;
}

vec3 getColor(vec3 origin, vec3 direction)
{
    float totalDistance = rayMarch(origin, direction);
    vec3 point = origin + direction * totalDistance;
    vec3 color = palette(length(point) / 15.0);
    return color;
}

void mainImage(out vec4 fragColor, vec2 fragCoord)
{
    //Prepare UV coordinate
    vec2 uv = fragCoord / iResolution.xy;
    uv = vec2(uv.x - 0.5, uv.y - 0.5);

    float aspect = iResolution.x / iResolution.y;
    uv.x = uv.x * aspect;

    float xtime = cos(iTime);
    float ytime = sin(iTime);
    //Spawn ray
    vec3 origin = vec3(xtime, ytime, iTime);
    vec3 direction = vec3(uv.x, uv.y, 1.0);

    direction.xy *= rotate2D(0.75 * iTime);

    direction = normalize(direction);

    //Get color for pixel
    fragColor = vec4(getColor(origin, direction), 1.0);
}
